from __future__ import annotations

from decimal import Decimal
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric(value: Any) -> Decimal:
    if value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def set_discount(
    order: dict,
    pct: Any,
    user_id: str,
    users: list[dict],
) -> dict:
    numeric_pct = _numeric(pct)

    # ORD-001: range validation runs first.
    if not (Decimal(0) <= numeric_pct <= Decimal(100)):
        raise BusinessRuleViolation("E5001", "Discount out of range")

    # ORD-002: LOOKUP returns the first live matching user's role.
    if numeric_pct > Decimal(20):
        role_id = ""
        for user in users:
            if user.get("DEL_FLG", "") != "Y" and user.get("USR_ID", "") == user_id:
                role_id = user.get("ROLE_ID", "")
                break

        if role_id not in ("MGR", "ADMIN"):
            raise BusinessRuleViolation(
                "E5002",
                "Discount over 20 percent requires manager role",
            )

    updated_order = order.copy()
    updated_order["DISC_PCT"] = pct
    return updated_order
